function renderBuybacks(){if(!(state.soldItems?.length||state.soldFixtures?.length))return;const shelf=document.createElement('details');shelf.className='buyback-shelf';shelf.innerHTML='<summary>Buy back</summary>'+[...(state.soldItems||[]).map((o,i)=>`<button data-buyback="${i}" ${state.money<buybackPrice(o)?'disabled':''}>${CATALOG[o.type].name} · $${buybackPrice(o)}</button>`),...(state.soldFixtures||[]).map(k=>`<button data-fixture-buyback="${k}" ${state.money<FIXTURES[k].price?'disabled':''}>${FIXTURES[k].name} · $${FIXTURES[k].price}</button>`)].join('');$('#catalog').append(shelf);wireBuybacks();for(const b of document.querySelectorAll('[data-fixture-buyback]'))b.onclick=()=>{if(!buyFixture(state,b.dataset.fixtureBuyback))return;buildRoom();rebuildObjects();afterEdit();};}
function wireBuybacks(){for(const button of document.querySelectorAll('[data-buyback]'))button.onclick=()=>{const i=+button.dataset.buyback,o=state.soldItems[i],price=buybackPrice(o);if(!editAllowed()||state.money<price)return;if(['barista','order','pickup'].includes(o.type)){if(walkable(o)&&state.objects.some(n=>walkable(n)&&overlap(o,n,.03))){toast('Clear the original station space first');return;}state.money-=price;state.soldItems.splice(i,1);state.objects.push(o);syncObject(o);afterEdit();return;}state.money-=price;state.soldItems.splice(i,1);state.inventory.push(o);afterEdit();toast('↩ Storage');};}
function sellFixed(key){if(!editAllowed())return;if(key==='bathroom'&&simulation?.parties.some(g=>['toBathroom','bathroom','bathroomWait'].includes(g.phase))){toast('Bathroom in use');return;}if(key==='nook'){const contents=state.objects.filter(o=>o.x>7.2);if(contents.some(occupied)){toast('Room in use');return;}state.inventory.push(...contents.filter(o=>o.type!=='nookArea'));const roomLights=state.lights.filter(o=>o.x>7.2);state.inventory.push(...roomLights);state.lights=state.lights.filter(o=>o.x<=7.2);state.objects=state.objects.filter(o=>!contents.includes(o));}if(!sellFixture(state,key))return;selected=null;buildRoom();rebuildObjects();afterEdit();}
function changeWindow(id){if(!editAllowed())return;state.soldWindows||=[];if(state.soldWindows.includes(id)){if(state.money<125){toast('Need $125');return;}state.money-=125;state.soldWindows=state.soldWindows.filter(x=>x!==id);}else{state.soldWindows.push(id);recordAssetSale(state,100);}recordChange(state);buildRoom();afterEdit();}
function resizeStation(){const b=getFacility(state,'barista');if(!editAllowed()||!b||occupied(b)||simulation?.barista&&['day-running','intervene'].includes(state.phase)){toast('Station in use');return;}if(b.compact){if(state.money<150)return;const expanded={...b,width:8.2,depth:2.6};if(state.objects.some(o=>o.id!==b.id&&walkable(o)&&overlap(expanded,o,.08))){toast('Clear space first');return;}state.money-=150;b.compact=false;b.width=8.2;b.depth=2.6;}else{recordAssetSale(state,125);b.compact=true;b.width=5.2;b.depth=1.8;}recordChange(state);syncObject(b);afterEdit();}
function openObjectMenu(hit,e){cancelPlacement();$('#inspection').innerHTML='';if(simulation&&!simulation.done)dayUI.pause();const menu=$('#objectMenu');menu.hidden=false;menu.style.left=clamp(e.clientX,8,innerWidth-225)+'px';menu.style.top=clamp(e.clientY,80,innerHeight-180)+'px';const win=hit.kind==='window',fixed=hit.kind==='fixture',surface=hit.kind==='surface',o=hit.kind==='item'?hit.value:null;selected=o;const sold=win&&state.soldWindows?.includes(hit.value);const name=win?'Window':fixed?FIXTURES[hit.value]?.name:surface?REPAIRS[hit.value]?.name||'Café':furnitureName(o);let choices='';if(win)choices=`<option value="window">${sold?'Restore · $125':'Sell · +$100'}</option>${!sold?`<option value="blind">${!state.blinds?.[hit.value]?'Add blinds · $35':state.blinds[hit.value]==='closed'?'Open blinds':'Close blinds'}</option>`:''}`;else if(fixed)choices=`<option value="fixed">Sell · +$${fixtureSalePrice(hit.value)}</option>`;else if(surface){choices=`<option value="surface">${state[hit.value]?'Customize':'Repair'}</option>`;if(['floor','paint'].includes(hit.value)&&state[hit.value])choices+=`<option value="finish">Sell finish · +$150</option>`;}else{if(o.type==='pickup'&&!o.twoHeights)choices+='<option value="counter-height">Two-height counter · $90</option>';if(o.type==='barista')choices+=`<option value="resize">${o.compact?'Larger · $150':'Smaller · +$125'}</option>`;else if(o.type!=='tableOutlet')choices+='<option value="move">Move</option><option value="inspect">Customize</option>';if(supportsCharging(o)&&!hasTableOutlet(state,o))choices+=`<option value="charging" ${state.money<TABLE_OUTLET_PRICE?'disabled':''}>Add charging outlet · $${TABLE_OUTLET_PRICE}</option>`;choices+=`<option value="sell" ${occupied(o)?'disabled':''}>Sell · +$${salePrice(o)}</option>`;}menu.innerHTML=`<button id="closeObjectMenu" aria-label="Close">×</button><b>${name}</b><select id="objectAction" aria-label="Object action"><option value="">Choose…</option>${choices}</select>`;$('#closeObjectMenu').onclick=()=>menu.hidden=true;$('#objectAction').onchange=ev=>{menu.hidden=true;const action=ev.target.value;if(action==='blind'){state.blinds||={};if(!state.blinds[hit.value]){if(state.money<35){toast('Need $35');return;}state.money-=35;state.blinds[hit.value]='closed';}else state.blinds[hit.value]=state.blinds[hit.value]==='closed'?'open':'closed';buildRoom();afterEdit();}if(action==='counter-height'){if(state.money<90){toast('Need $90');return;}state.money-=90;o.twoHeights=true;syncObject(o);afterEdit();}if(action==='window')changeWindow(hit.value);if(action==='fixed')sellFixed(hit.value);if(action==='resize')resizeStation();if(action==='charging'){if(!editAllowed())return;const socket=installTableOutlet(state,o,'charge-'+nextId++);if(socket){recordChange(state);syncObject(socket);afterEdit();}}if(action==='move')beginMove(o);if(action==='inspect')inspect(o);if(action==='sell')sellItem();if(action==='surface')inspect(hit.value);if(action==='finish'&&state[hit.value]){state[hit.value]=false;recordAssetSale(state,150);buildRoom();afterEdit();}};}

const editKeys=['assetSaleTotal','blinds','clean','waste','floor','paint','objects','lights','atmosphere','renovations','soldFixtures','soldWindows','soldItems','inventory','surfaceColors','floorPattern','upgradeCredits'];let undoStack=[],redoStack=[],lastEdit=null,applyingHistory=false;
function editSnapshot(){const data={budget:state.money-(state.liveCredited||0)+(state.hintSpent||0)};for(const k of editKeys)if(state[k]!==undefined)data[k]=JSON.parse(JSON.stringify(state[k]));return data;}
function historyButtons(){$('#undoEdit').disabled=!undoStack.length||!canEdit(state);$('#redoEdit').disabled=!redoStack.length||!canEdit(state);}
function resetEdits(){undoStack=[];redoStack=[];lastEdit=editSnapshot();historyButtons();}
function rememberEdit(){if(applyingHistory)return;const now=editSnapshot();if(lastEdit&&JSON.stringify(now)!==JSON.stringify(lastEdit)){undoStack.push(lastEdit);if(undoStack.length>30)undoStack.shift();redoStack=[];}lastEdit=now;historyButtons();}
function applyHistory(from,to){if(!from.length||!canEdit(state))return;cancelPlacement();const target=from.at(-1);if(simulation&&target.renovations?.bathroom!==state.renovations?.bathroom&&simulation.parties.some(g=>['toBathroom','bathroom','bathroomWait'].includes(g.phase))){toast('Bathroom in use');return;}if(state.objects.some(o=>occupied(o)&&(()=>{const n=target.objects.find(n=>n.id===o.id);return !n||['x','z','r','width','depth'].some(k=>n[k]!==o[k]);})())){toast('Furniture is in use');return;}dayUI.pause();to.push(editSnapshot());from.pop();const live=state.liveCredited||0;for(const k of editKeys)delete state[k];for(const k of editKeys)if(target[k]!==undefined)state[k]=JSON.parse(JSON.stringify(target[k]));state.money=target.budget+live-(state.hintSpent||0);selected=null;buildRoom();rebuildObjects();applyingHistory=true;afterEdit();applyingHistory=false;lastEdit=editSnapshot();historyButtons();}
$('#undoEdit').onclick=()=>applyHistory(undoStack,redoStack);$('#redoEdit').onclick=()=>applyHistory(redoStack,undoStack);
buildRoom();rebuildObjects();setView('wall');resize();updateBudget();$('#loading').remove();window.addEventListener('resize',resize);
function openClipboard(){selected=null;$('#clipboardBody').hidden=false;document.body.dataset.panel='open';$('#shopToggle').setAttribute('aria-expanded','true');$('#chevron').textContent='−';selectTab(cleanupReady(state)?'missions':'prepare');resize();requestForecast()}
dayUI=createDayUI(state,{changed:()=>{save();updateBudget();renderInspection();renderCatalog();updateZones();resize()},save,market:()=>{if(!held&&!$('#clipboardBody').hidden)renderCatalog()},prepare:()=>selectTab(cleanupReady(state)?'missions':'prepare'),cancel:cancelPlacement,begin:startDaySimulation,renovate:()=>{resetEdits();clearGuests();selectTab('missions');rebuildObjects();buildRoom();updateZones();requestForecast();},adjust:()=>{clearGuests();openClipboard()},intervene:openClipboard,resume:()=>{selected=null;$('#clipboardBody').hidden=true;$('#shopToggle').setAttribute('aria-expanded','false');$('#chevron').textContent='+';document.body.dataset.catalog='';document.body.dataset.panel='closed';resize()},focusAlert:a=>{if(a.point){setView('wall');orbit.target.set(a.point.x,.3,a.point.z);zoom=1.3;updateCamera();pathwaysVisible=true;$('#pathwaysToggle').setAttribute('aria-pressed',true);updatePathways()}},toast});
renderCatalog();for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-pressed',b.dataset.tab===activeTab);$('#open').onclick=()=>dayUI.requestRun();$('#storeToggle').onclick=()=>$('#shopToggle').click();dayUI.restore();if(['day-running','intervene'].includes(state.phase)){startDaySimulation('day',state.runSnapshot||cafeSnapshot(state),state.runElapsed||0);if(state.phase==='intervene')openClipboard()}requestForecast();resetEdits();save();requestAnimationFrame(frame);
